package com.cestasdamel.erp.repository; import com.cestasdamel.erp.model.Product; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*;
public interface ProductRepository extends JpaRepository<Product,Long>{ List<Product> findAllByDeletedAtIsNullOrderByNameAsc(); Optional<Product> findByIdAndDeletedAtIsNull(Long id); boolean existsByCategoryIdAndDeletedAtIsNull(Long categoryId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select p from Product p where p.id=:id and p.deletedAt is null") Optional<Product> lockById(@Param("id") Long id); }
